"""Static validation for SQL written by users or generated by an LLM.

Layered with runtime guards in executor.py (READ ONLY transaction, statement_timeout, search_path
restricted to the workspace schema, row cap, optional read-only database role).
"""
from __future__ import annotations

import re

import sqlglot
from sqlglot import exp

MAX_SQL_LENGTH = 20000

_FORBIDDEN_NODES = tuple(
    getattr(exp, n) for n in (
        "Insert", "Update", "Delete", "Merge", "Create", "Drop", "Alter", "AlterColumn", "Command", "Copy", "Grant",
        "Set", "Transaction", "Commit", "Rollback", "Into", "Lock", "TruncateTable", "Use", "LoadData", "Pragma",
        "Describe", "Analyze", "Revoke", "Kill",
    ) if hasattr(exp, n)
)
_BLOCKED_FUNC_PREFIXES = ("pg_", "lo_", "dblink", "txid_", "query_to_xml", "table_to_xml", "cursor_to_xml",
                          "database_to_xml", "schema_to_xml", "xpath")
_BLOCKED_FUNCS = {
    "set_config", "current_setting", "nextval", "setval", "currval", "lastval", "version", "current_version", "inet_server_addr",
    "inet_server_port", "inet_client_addr", "current_user", "session_user", "user", "current_schemas",
    "has_table_privilege", "has_schema_privilege", "to_regclass", "format_type", "obj_description",
    "col_description", "read_csv", "read_parquet", "generate_series",
    # amplification / fingerprinting helpers (memory DoS is not bounded by work_mem)
    "repeat", "current_database", "current_query", "current_catalog", "pg_backend_pid",
}
_BLOCKED_SCHEMAS = {"pg_catalog", "information_schema", "pg_toast", "public", "lumen_meta"}


class UnsafeSQLError(ValueError):
    pass


def _func_name(node: exp.Expression) -> str:
    if isinstance(node, exp.Anonymous):
        return str(node.this).lower()
    name = node.sql_name() if hasattr(node, "sql_name") else node.key
    return name.lower()


def _visible_ctes(node: exp.Expression) -> set[str]:
    """CTE names actually in scope for a bare table reference.

    A bare name is a CTE reference only when a WITH that *encloses* this node defines it. Collecting CTE
    names globally (anywhere in the tree) is unsafe: a dummy CTE in an unrelated sub-query would whitelist
    a same-named real table elsewhere (e.g. ``FROM pg_class, (WITH pg_class AS (...) ...)``). A non-recursive
    CTE is also not visible inside its own definition body, where the name denotes a physical table.
    """
    ancestors: set[int] = set()
    p = node.parent
    while p is not None:
        ancestors.add(id(p))
        p = p.parent
    names: set[str] = set()
    cur = node.parent
    while cur is not None:
        # The WITH clause is a child of a Select/Query; its arg key varies by sqlglot version ("with"/"with_").
        for val in cur.args.values() if isinstance(cur, exp.Expression) else ():
            if isinstance(val, exp.With):
                recursive = bool(val.args.get("recursive"))
                for cte in val.expressions:
                    if not recursive and id(cte) in ancestors:
                        continue  # inside this CTE's own body: the name is a physical table, not the CTE
                    names.add(cte.alias_or_name.lower())
        cur = cur.parent
    return names


def validate_select(sql: str, schema: str, allowed_tables: set[str], row_limit: int | None = None) -> str:
    """Return a normalised, LIMIT-ed SELECT or raise UnsafeSQLError explaining why it was rejected."""
    if not sql or not sql.strip():
        raise UnsafeSQLError("The query is empty")
    if len(sql) > MAX_SQL_LENGTH:
        raise UnsafeSQLError("The query is too long")
    stripped = sql.strip().rstrip(";").strip()
    if re.search(r"\$(?:[A-Za-z_][A-Za-z0-9_]*)?\$|\\\\copy|\\g\b", stripped):  # $$ and tagged $tag$ quoting
        raise UnsafeSQLError("Dollar-quoted strings and psql meta-commands are not allowed")
    try:
        statements = [s for s in sqlglot.parse(stripped, read="postgres") if s is not None]
    except Exception as e:  # ParseError / TokenError
        raise UnsafeSQLError(f"Could not parse SQL: {e}") from e
    if len(statements) != 1:
        raise UnsafeSQLError("Exactly one SELECT statement is allowed")
    tree = statements[0]
    if not isinstance(tree, exp.Query):
        raise UnsafeSQLError("Only SELECT queries are allowed")
    if any(w.args.get("recursive") for w in tree.find_all(exp.With)):
        raise UnsafeSQLError("Recursive CTEs are not allowed")

    allowed = {t.lower() for t in allowed_tables}
    for node in tree.walk():
        if isinstance(node, _FORBIDDEN_NODES):
            raise UnsafeSQLError(f"'{node.key.upper()}' is not allowed; queries must be read-only")
        if isinstance(node, exp.Lock):
            raise UnsafeSQLError("Row locking clauses are not allowed")
        if isinstance(node, exp.Table):
            name = (node.name or "").lower()
            db = (node.db or "").lower()
            if node.args.get("catalog"):
                raise UnsafeSQLError("Cross-database references are not allowed")
            if isinstance(node.this, exp.Func) or not name:
                raise UnsafeSQLError("Table functions are not allowed")
            if db and db != schema.lower():
                raise UnsafeSQLError(f"Access to schema '{db}' is not allowed")
            if db in _BLOCKED_SCHEMAS:
                raise UnsafeSQLError(f"Access to schema '{db}' is not allowed")
            if not db and name in _visible_ctes(node):
                continue
            if name.startswith("_raw_") or name not in allowed:
                raise UnsafeSQLError(f"Unknown or inaccessible table '{node.name}'")
        if isinstance(node, exp.Func):
            name = _func_name(node)
            if name in _BLOCKED_FUNCS or name.startswith(_BLOCKED_FUNC_PREFIXES):
                raise UnsafeSQLError(f"Function '{name}' is not allowed")
    out = tree.sql(dialect="postgres")
    if row_limit:
        out = f"SELECT * FROM ({out}) AS _lumen_q LIMIT {int(row_limit) + 1}"
    return out


def referenced_tables(sql: str) -> set[str]:
    try:
        tree = sqlglot.parse_one(sql, read="postgres")
    except Exception:
        return set()
    ctes = {c.alias_or_name.lower() for c in tree.find_all(exp.CTE)}
    return {t.name.lower() for t in tree.find_all(exp.Table) if t.name and t.name.lower() not in ctes}
